<?php
namespace App\Http\Controllers;
use App\Models\{Category,Discount,Food,InventoryTransaction,Order,Payment,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class AdminController extends Controller {
 public function dashboard(){return view('admin.dashboard',['revenue'=>Order::where('status','completed')->sum('total'),'orders'=>Order::count(),'pending'=>Order::where('status','pending')->count(),'customers'=>User::where('role','customer')->count(),'lowStock'=>Food::whereColumn('quantity','<=','low_stock_threshold')->count(),'recent'=>Order::with('user')->latest()->take(8)->get()]);}
 public function foods(){return view('admin.foods',['foods'=>Food::with('category')->latest()->paginate(15),'categories'=>Category::all()]);}
 public function saveFood(Request $r,Food $food=null){$d=$r->validate(['category_id'=>'required|exists:categories,id','name'=>'required|max:150','description'=>'nullable','price'=>'required|numeric|min:0','quantity'=>'required|integer|min:0','low_stock_threshold'=>'required|integer|min:0','is_available'=>'boolean','is_featured'=>'boolean','is_best_seller'=>'boolean']);$d['slug']=Str::slug($d['name']).'-'.Str::lower(Str::random(5));$d['is_available']=$r->boolean('is_available');$d['is_featured']=$r->boolean('is_featured');$d['is_best_seller']=$r->boolean('is_best_seller');if($food){$food->update($d);}else{Food::create($d);}return back()->with('success','Food saved.');}
 public function deleteFood(Food $food){$food->delete();return back()->with('success','Food removed.');}
 public function categories(){return view('admin.categories',['categories'=>Category::withCount('foods')->get()]);} public function saveCategory(Request $r,Category $category=null){$d=$r->validate(['name'=>'required|max:100|unique:categories,name'.($category?', '.$category->id:'') ,'description'=>'nullable']);$d['slug']=Str::slug($d['name']);$category?$category->update($d):Category::create($d);return back()->with('success','Category saved.');} public function deleteCategory(Category $category){abort_if($category->foods()->exists(),422,'Cannot remove a category containing foods.');$category->delete();return back()->with('success','Category removed.');}
 public function orders(){return view('admin.orders',['orders'=>Order::with('user','payment')->latest()->paginate(20)]);} public function updateOrder(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:pending,confirmed,preparing,ready,out_for_delivery,completed,cancelled']);DB::transaction(function()use($d,$order,$r){if($order->stock_deducted_at===null && in_array($d['status'],['confirmed','preparing','ready','out_for_delivery','completed'])){foreach($order->items as $item){$food=Food::lockForUpdate()->find($item->food_id);abort_if(!$food||$food->quantity<$item->quantity,422,"Insufficient stock for {$item->food_name}");$food->decrement('quantity',$item->quantity);InventoryTransaction::create(['food_id'=>$food->id,'user_id'=>$r->user()->id,'quantity_change'=>-$item->quantity,'type'=>'order','reference'=>$order->order_number]);}$order->stock_deducted_at=now();}$order->status=$d['status'];$order->save();});return back()->with('success','Order status updated.');}
 public function payments(){return view('admin.payments',['payments'=>Payment::with('order.user')->latest()->paginate(20)]);} public function verifyPayment(Request $r,Payment $payment){$d=$r->validate(['status'=>'required|in:paid,failed,refunded']);$payment->update(['status'=>$d['status'],'verified_at'=>now(),'verified_by'=>$r->user()->id]);return back()->with('success','Payment updated.');}
 public function inventory(){return view('admin.inventory',['foods'=>Food::with('category')->paginate(30),'history'=>InventoryTransaction::with('food')->latest()->take(20)->get()]);} public function adjustStock(Request $r,Food $food){$d=$r->validate(['quantity_change'=>'required|integer|not_in:0','notes'=>'nullable|max:500']);DB::transaction(function()use($d,$food,$r){$f=Food::lockForUpdate()->findOrFail($food->id);abort_if($f->quantity+$d['quantity_change']<0,422,'Stock cannot be negative.');$f->increment('quantity',$d['quantity_change']);InventoryTransaction::create(['food_id'=>$f->id,'user_id'=>$r->user()->id,'quantity_change'=>$d['quantity_change'],'type'=>'adjustment','notes'=>$d['notes']??null]);});return back()->with('success','Inventory adjusted.');}
 public function discounts(){return view('admin.discounts',['discounts'=>Discount::latest()->paginate(20)]);} public function saveDiscount(Request $r){$d=$r->validate(['code'=>'required|alpha_dash|unique:discounts,code','type'=>'required|in:percent,fixed','value'=>'required|numeric|min:0','minimum_order'=>'nullable|numeric|min:0','expires_at'=>'nullable|date']);$d['code']=strtoupper($d['code']);$d['is_active']=$r->boolean('is_active',true);Discount::create($d);return back()->with('success','Promotion created.');}
}
